"""Build an offline HTML viewer and render SVG/PDF exports using Chromium."""
from pathlib import Path
import json, html, asyncio
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parents[1]; O=R/'docs/bpmn'
meta=json.loads((O/'model.json').read_text()); xml=(O/'yol1-enterprise.bpmn').read_text(); lib=(O/'vendor/bpmn-viewer.js').read_text()
page='''<!doctype html><html lang="es"><meta charset="utf-8"><title>YOL1 Enterprise · Modelo de onboarding</title><style>
*{box-sizing:border-box}body{margin:0;font:15px Arial,sans-serif;color:#143b35;background:#f5f7fa}header{background:#103e34;color:white;padding:22px 28px}h1{margin:0 0 8px;font-size:25px}header p{margin:0;color:#d5e8e1}nav{display:flex;gap:7px;flex-wrap:wrap;padding:16px}button{font:inherit;cursor:pointer;padding:10px 14px;border:1px solid #aabeb5;border-radius:8px;background:white;color:#143b35}button[aria-pressed=true]{background:#dfff80}#canvas{height:65vh;min-height:430px;background:white;margin:0 16px;border:1px solid #cedbd6;border-radius:12px}section{padding:16px 28px}h2{margin:0 0 10px}li{margin-bottom:10px;line-height:1.5}.tools{display:flex;gap:8px;margin:0 16px 12px}#detail{background:#edf3e6;padding:14px;border-radius:8px}a{color:#006556}#status{margin:8px 28px}footer{padding:24px;background:#e3ebe6}
</style><header><h1>YOL1 Enterprise · Onboarding</h1><p>Modelo descriptivo del código actual · BPMN 2.0 · No ejecutable · Fuente REV</p></header><nav id="tabs"></nav><div class="tools"><button id="fit">Ajustar</button><button id="plus">Acercar +</button><button id="minus">Alejar −</button><button id="download">Descargar BPMN</button><button id="svg">Descargar SVG del proceso</button></div><div id="canvas" aria-label="Diagrama BPMN"></div><p id="status" role="status"></p><section><h2 id="title"></h2><p id="subtitle"></p><ul id="notes"></ul><div id="detail">Haz clic en una actividad para consultar su detalle.</div><p id="source"></p></section><footer>Lectura de izquierda a derecha. Círculo fino: inicio; círculo grueso: término; rectángulo: actividad; rombo X: decisión exclusiva; rombo +: ramas paralelas. Los controles de demo no representan un proceso de producción.<br>El fin de un intento fallido no significa aprobación. Identidad y KYB son independientes; ambas aprobaciones son necesarias para abrir la cuenta.<br>Importa los SVG en Figma para editar formas, conectores y textos. Conserva el BPMN para editar la semántica del proceso en un modelador BPMN.<br>Visor bpmn-js, licencia incluida en el paquete.</footer><script>LIB</script><script>
const data=__DATA__, xml=__XML__;const viewer=new BpmnJS({container:'#canvas'});window.viewer=viewer;window.models=data.maps;window.errors=[];
const colors=['#e7efff','#f0e7ff','#fff2d2','#dff4ec','#e4f5f3','#e8effd','#fce8ed','#fff0dc'];
function save(content,name,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000)}
function color(){const registry=viewer.get('elementRegistry');registry.getAll().forEach(e=>{const g=registry.getGraphics(e);const shape=g?.querySelector('.djs-visual > :first-child');if(!shape)return;const type=e.type;if(/Task|Activity/.test(type)){shape.setAttribute('fill',colors[window.index]);shape.style.fill=colors[window.index];shape.setAttribute('stroke','#244b47')}if(/Gateway/.test(type)){shape.style.fill='#fff0b3';shape.setAttribute('stroke','#976810')}if(type==='bpmn:StartEvent'){shape.style.fill='#c9f0d4'}if(type==='bpmn:EndEvent'){shape.style.fill='#d2e7ed'}})}
window.openMap=async function(index){window.index=index;const m=data.maps[index];const result=await viewer.open(m.id+'_diagram');if(result.warnings.length)window.errors.push(...result.warnings.map(x=>x.message));color();viewer.get('canvas').zoom('fit-viewport');document.querySelector('#title').textContent=m.title;document.querySelector('#subtitle').textContent=m.subtitle;const notes=document.querySelector('#notes');notes.replaceChildren();m.notes.forEach(n=>{const li=document.createElement('li');li.textContent=n;notes.append(li)});document.querySelectorAll('#tabs button').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));document.querySelector('#source').innerHTML='Fuente: <a href="https://github.com/bahumadap/onboarding/blob/'+data.revision+'/'+m.source+'">'+m.source+'</a>';document.querySelector('#detail').textContent='Haz clic en una actividad para consultar su detalle.';document.querySelector('#status').textContent=(index+1)+' / '+data.maps.length+' · Arrastra para mover el diagrama.';return true};
data.maps.forEach((m,i)=>{const b=document.createElement('button');b.textContent=m.title;b.onclick=()=>openMap(i);document.querySelector('#tabs').append(b)});
viewer.on('element.click',({element})=>{const n=data.maps[window.index].nodes.find(n=>n.id===element.id);if(n)document.querySelector('#detail').textContent=n.label+' — '+n.doc});
document.querySelector('#fit').onclick=()=>viewer.get('canvas').zoom('fit-viewport');document.querySelector('#plus').onclick=()=>viewer.get('canvas').zoom(viewer.get('canvas').zoom()*1.3);document.querySelector('#minus').onclick=()=>viewer.get('canvas').zoom(viewer.get('canvas').zoom()/1.3);document.querySelector('#download').onclick=()=>save(xml,'yol1-enterprise.bpmn','application/xml');document.querySelector('#svg').onclick=async()=>save((await viewer.saveSVG()).svg,data.maps[window.index].id+'.svg','image/svg+xml');
(async()=>{try{const r=await viewer.importXML(xml);window.errors.push(...r.warnings.map(x=>x.message));await openMap(0);window.ready=true}catch(e){window.errors.push(e.message);document.querySelector('#status').textContent='Error: '+e.message;window.ready=true}})();
</script></html>'''
page=page.replace('REV',meta['revision'][:7]).replace('LIB',lib).replace('__DATA__',json.dumps(meta,ensure_ascii=False).replace('</','<\\/')).replace('__XML__',json.dumps(xml,ensure_ascii=False).replace('</','<\\/'))
(O/'onboarding.html').write_text(page)
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox'])
 pg=browser.new_page(viewport={'width':1800,'height':1100});pg.set_content(page);pg.wait_for_function('window.ready');assert not pg.evaluate('window.errors'),pg.evaluate('window.errors')
 sections=[]
 for i,m in enumerate(meta['maps']):
  pg.evaluate('(i)=>window.openMap(i)',i)
  svg=pg.evaluate('async ()=>(await viewer.saveSVG()).svg');(O/(m['id']+'.svg')).write_text(svg)
  sections.append('<article><h1>'+html.escape(m['title'])+'</h1><p>'+html.escape(m['subtitle'])+'</p><div class="diagram">'+svg+'</div><ul>'+''.join('<li>'+html.escape(n)+'</li>' for n in m['notes'])+'</ul><small>Fuente: '+m['source']+' · '+meta['revision'][:7]+' · Modelo descriptivo de la demo</small></article>')
  print('OK',m['id'],flush=True)
 assert not pg.evaluate('window.errors'),pg.evaluate('window.errors')
 pg.evaluate('window.openMap(0)');pg.screenshot(path='/tmp/yol1-bpmn-overview.png',full_page=True)
 printable='<!doctype html><html lang="es"><meta charset="utf-8"><style>@page{size:A3 landscape;margin:12mm}body{font:12px Arial;color:#173e35}article{break-after:page}article:last-child{break-after:auto}h1{font-size:24px;margin:0 0 10px}li{margin:5px 0}.diagram{height:185mm;width:390mm}.diagram svg{width:100%;height:100%}small{color:#567}</style>'+''.join(sections)+'</html>'
 (O/'imprimir.html').write_text(printable);pg.set_content(printable);pg.pdf(path=str(O/'yol1-enterprise.pdf'),prefer_css_page_size=True,print_background=True)
 browser.close()
